-- ============================================================
--  Student enrollment import  —  members-site (DrumKit / ZADA)
--  Import via Hostinger phpMyAdmin  ->  Import tab.
--  1) creates the 'students' enrollment table (all form fields)
--  2) creates one 'users' login account per unique email
--  3) links each enrollment to its user account by email
--  Password is left blank: students set one via "Forgot password",
--  or an admin sets it. Accounts start as 'expired' (no free access).
--  Blank text fields are stored as '' (only age/amount/date use NULL).
--  Safe to import once. Generated 2026-06-30 22:54.
-- ============================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS students (
  id              INT AUTO_INCREMENT PRIMARY KEY,
  user_id         INT NULL,
  enrolled_at     DATETIME NULL,
  email           VARCHAR(190) NOT NULL,
  last_name       VARCHAR(100) DEFAULT '',
  first_name      VARCHAR(150) DEFAULT '',
  middle_initial  VARCHAR(10)  DEFAULT '',
  full_name       VARCHAR(255) DEFAULT '',
  age             INT NULL,
  date_of_birth   DATE NULL,
  parent_guardian VARCHAR(255) DEFAULT '',
  address         VARCHAR(500) DEFAULT '',
  phone           VARCHAR(50)  DEFAULT '',
  experience      VARCHAR(50)  DEFAULT '',
  program         VARCHAR(255) DEFAULT '',
  program_amount  DECIMAL(10,2) NULL,
  currency        CHAR(3) DEFAULT 'PHP',
  proof_url       VARCHAR(500) DEFAULT '',
  payment_status  VARCHAR(50)  DEFAULT '',
  source_file     VARCHAR(255) DEFAULT '',
  created_at      DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_email (email),
  KEY idx_user (user_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ===== USERS (one per unique email) =====

